INSERT INTO case_studies (id, slug, title, summary, status, featured, sort_order, created_at, updated_at, published_at) VALUES ('8h1nM05brs4UI9JxF112u', 'estelar', 'Estelar', 'As Art Director, I led the logo and campaign design for the launch of Salami Súper Especial Estelar in New York—the first 100% Dominican salami introduced to the U.S. market. 
INSERT INTO case_studies (id, slug, title, summary, status, featured, sort_order, created_at, updated_at, published_at) VALUES ('_W3CNdKyEroebstm03uOy', 'alkasa-30th-aniversary', 'Alkasa - 30th Aniversary', 'As Art Director, I led the branding and visual identity for Alkasa’s 30th anniversary, crafting a logo and graphic language that celebrate travel and exploration.', 'published', 1, 0, 1777962093133, 1777997570911, 1777997570911);
INSERT INTO case_studies (id, slug, title, summary, status, featured, sort_order, created_at, updated_at, published_at) VALUES ('7gm2H-4lgOgDL9MWth-7e', 'restaurante-temporada-temporada-chifa', 'Restaurante Temporada - Temporada Chifa', 'Rediseño de logo para Temporada Chifa y diseño de los diferentes menús (menú de platos - menú tragos y cocteles - carta de vinos) durante esa  temporada especializada en la gastronomía Chifa.', 'published', 0, 0, 1777963435453, 1777997651990, 1777997651990);
INSERT INTO case_studies (id, slug, title, summary, status, featured, sort_order, created_at, updated_at, published_at) VALUES ('Ki7vphBTNqabA9jhaf5Ub', 'liquid-beer', 'Liquid Beer', 'Liquid Beer | 10 Years was developed as a proposal for an internal design contest celebrating the agency’s 10-year milestone. The concept, “Helping Hands,” was inspired by the collective effort behind every creative achievement — the hands that build, push ideas forward, and support one another through tight deadlines and challenges.
